package ru.kstolu.app;
import android.app.*;import android.os.*;import android.graphics.*;import android.graphics.drawable.RippleDrawable;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.io.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w390dp-h844dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class PolishUiTest {
 private org.robolectric.android.controller.ActivityController<MainActivity> controller;private MainActivity host;
 @Before public void setup(){ApiClient.configureForTests(url->{throw new AssertionError("Visual change must not call AI");});controller=Robolectric.buildActivity(MainActivity.class).setup();host=controller.get();}
 @After public void close(){controller.pause().stop().destroy();ApiClient.restoreTransport();}
 private JSONObject item(boolean timer)throws Exception{JSONObject r=new JSONObject("{\"status\":\"ok\",\"title\":\"Паста с томатами\",\"servings\":2,\"ingredients\":[{\"name\":\"Томаты\",\"amount\":200,\"unit\":\"g\"}],\"steps\":[{\"title\":\"Приготовьте соус\",\"body\":\"Прогрейте томаты на среднем огне. Добавьте немного воды от пасты, если томаты начинают прилипать.\",\"ingredient_indexes\":[0]}]}");if(timer)r.getJSONArray("steps").getJSONObject(0).put("timer_seconds",180).put("timer_hint","Запустите, когда добавите томаты в сковороду.");return new JSONObject().put("recipe",r).put("portions",2).put("currency","RUB");}
 private void layout(View v,int width){for(int i=0;i<3;i++){v.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(844,View.MeasureSpec.EXACTLY));v.layout(0,0,width,844);Shadows.shadowOf(Looper.getMainLooper()).idle();}}
 private void draw(View v,int width,String name)throws Exception{Bitmap b=Bitmap.createBitmap(width,844,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));File dir=new File("build/visual-qa-1.2.5");dir.mkdirs();try(FileOutputStream f=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,f);}b.recycle();}
 private void flat(Button b){assertTrue(b.getBackground() instanceof RippleDrawable);assertTrue(b.getClipToOutline());assertNull(b.getStateListAnimator());assertEquals(0,b.getElevation(),0);assertEquals(0,b.getTranslationZ(),0);Outline outline=new Outline();b.getOutlineProvider().getOutline(b,outline);assertTrue("rounded outline",outline.getRadius()>=16);}
 @Test public void allPillsFitNarrowAndWideScreensWithRoundedFlatGeometry()throws Exception{
  SousChefSheet chat=new SousChefSheet(host,item(true),()->0,()->0);chat.show();Dialog d=org.robolectric.shadows.ShadowDialog.getLatestDialog();View sheet=d.getWindow().getDecorView().findViewWithTag("sous-sheet"),viewport=(View)sheet.getParent();
  for(int width:new int[]{320,390,600}){layout(viewport,width);chat.applyViewport(0,24,0,24,0,false);layout(viewport,width);LinearLayout row=sheet.findViewWithTag("sous-chips");assertEquals(3,row.getChildCount());int last=0;for(int i=0;i<3;i++){Button b=(Button)row.getChildAt(i);flat(b);assertTrue(b.getHeight()>=48);assertTrue(b.getLeft()>=last);assertTrue(b.getRight()<=row.getWidth());assertEquals(Gravity.CENTER,b.getGravity());assertNull(b.getCompoundDrawables()[0]);for(int line=0;line<b.getLayout().getLineCount();line++)assertEquals(0,b.getLayout().getEllipsisCount(line));Outline outline=new Outline();b.getOutlineProvider().getOutline(b,outline);assertEquals(24,outline.getRadius(),0);last=b.getRight()+8;}draw(viewport,width,"chat-"+width);}
  d.dismiss();
 }
 @Test public void pillPressKeepsShapeAndStillFillsQuestionWithoutSending()throws Exception{new SousChefSheet(host,item(true),()->0,()->0).show();Dialog d=org.robolectric.shadows.ShadowDialog.getLatestDialog();View sheet=d.getWindow().getDecorView().findViewWithTag("sous-sheet"),viewport=(View)sheet.getParent();layout(viewport,390);LinearLayout row=sheet.findViewWithTag("sous-chips");Button b=(Button)row.getChildAt(0);b.setPressed(true);flat(b);draw(viewport,390,"chat-pressed");b.setPressed(false);b.performClick();EditText input=sheet.findViewWithTag("sous-input");assertEquals("Чем заменить?",input.getText().toString());d.dismiss();}
 private void spacing(boolean timer)throws Exception{host.getSharedPreferences("cooking",0).edit().clear().commit();InlineCooking cooking=new InlineCooking(host,item(timer));ScrollView root=new ScrollView(host);root.setBackgroundColor(0xfff7f9f3);root.setPadding(20,20,20,20);root.addView(cooking);host.setContentView(root);layout(root,390);Button ask=cooking.findViewWithTag("cooking-sous-action");View control=cooking.findViewWithTag(timer?"cooking-timer":"cooking-add-timer");assertNotNull(ask);assertNotNull(control);flat(ask);assertTrue("At least 16dp visible gap",control.getTop()-ask.getBottom()>=16);assertTrue(ask.getHeight()>=48);assertTrue("Timer readable",control.getHeight()>=48);draw(root,390,timer?"cooking-timer":"cooking-add-timer");}
 @Test public void presetTimerIsSeparateFromChefAction()throws Exception{spacing(true);}
 @Test public void addTimerIsSeparateFromChefAction()throws Exception{spacing(false);}
}
